create role anon;create role authenticated;create role service_role;
create schema mschool;
create table mschool.users(id text primary key,name text,role_type text,status text);
create table mschool.staff_access(user_id text,auth_user_id uuid default gen_random_uuid(),role_type text,is_active boolean default true);
create table mschool.payroll_reviewer_accounts(user_id text primary key,auth_user_id uuid);
create table mschool.schedules(id bigint generated by default as identity primary key,date date,worker_id text,worker_name text,role_type text,shift text,hours numeric,job_desc text,hourly_wage numeric);
create table mschool.flow_operations(actor_id text,kind text,result jsonb);
create table mschool.payroll_rates(worker_id text not null references mschool.users(id),effective_from date not null,hourly_wage numeric(10,2)not null check(hourly_wage>=0 and hourly_wage<=100000),updated_by text not null,updated_at timestamptz not null default now(),primary key(worker_id,effective_from));
create table mschool.payroll_months(id uuid primary key default gen_random_uuid(),month date not null unique check(extract(day from month)=1),stage text not null default'yuting'check(stage in('yuting','enru','wife','pastor','approved')),revision bigint not null default 1,saved boolean not null default false,snapshot jsonb not null default '{}',folder_id text,folder_lease timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table mschool.payroll_photos(id uuid primary key,month_id uuid not null references mschool.payroll_months(id),drive_file_id text not null unique,file_name text not null,uploaded_by text not null,uploaded_stage text not null,created_at timestamptz not null default now());
create table mschool.payroll_audit(id bigint generated always as identity primary key,month_id uuid references mschool.payroll_months(id),actor_id text not null,action text not null,from_stage text,to_stage text,comment text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table mschool.payroll_notifications(month_id uuid,stage text);
-- Only the local fixture substitutes session lookup. Production resolver is never changed.
create function public.school_resolve_session(p_hash text)returns jsonb language sql stable as $$select to_jsonb(u)from mschool.users u where id=p_hash$$;
create function mschool.payroll_queue(b mschool.payroll_months)returns void language sql as $$insert into mschool.payroll_notifications values(b.id,b.stage)$$;
create function mschool.flow_replay(text,text,uuid,jsonb)returns jsonb language sql as $$select null::jsonb$$;
create function mschool.flow_record(text,text,uuid,jsonb,jsonb)returns jsonb language sql as $$select $5$$;
insert into mschool.users values('2026M0001','測試牧師','同工','在班'),('2026M0002','測試師母','同工','在班'),('2026M0003','測試恩茹','同工','在班'),('2026M0004','測試鈺庭','同工','在班'),('2026T9001','測試老師','同工','在班'),('2026P9001','測試工讀一','工讀生','在班'),('2026P9002','測試工讀二','工讀生','在班');
insert into mschool.staff_access(user_id,role_type)select id,role_type from mschool.users where id like'2026M%';
insert into mschool.payroll_reviewer_accounts select user_id,auth_user_id from mschool.staff_access;
