insert into mschool.flow_operations select v.actor,'schedules',jsonb_build_object('proposed',jsonb_build_array(jsonb_build_object('worker_id',s.worker_id,'date',s.date,'shift',s.shift)))from mschool.schedules s join(values('2026T9001','2026M0004'),('2026T9001','2026M0003'),('2026P9001','2026M0004'),('2026P9002','2026M0003'))v(worker,actor)on v.worker=s.worker_id;
